<?php

declare(strict_types=1);
namespace App\Modules\Inventory\Infrastructure;
use App\Exceptions\ApiException;
use App\Modules\TenantShop\Infrastructure\ShopContext;
use CodeIgniter\Database\BaseConnection;
final class IntakeQuery{
 public function __construct(private readonly BaseConnection $database){}
 /** @return list<array<string,mixed>> */ public function listing(ShopContext $c): array{return $this->database->table('stock_intakes')->select('public_id,intake_kind,status,reference,occurred_at,posted_at,created_at')->where(['tenant_id'=>$c->tenantId,'shop_id'=>$c->shopId])->orderBy('created_at','DESC')->get(50)->getResultArray();}
 /** @return array<string,mixed> */ public function detail(ShopContext $c,string $id): array{$h=$this->database->table('stock_intakes')->select('public_id,intake_kind,status,reference,notes,occurred_at,device_local_offset_minutes,posted_at,created_at,updated_at')->where(['tenant_id'=>$c->tenantId,'shop_id'=>$c->shopId,'public_id'=>strtolower($id)])->get()->getRowArray();if(!$h)throw new ApiException('INTAKE_NOT_FOUND','The Stock Intake was not found.',404);$h['items']=$this->database->table('stock_intake_items i')->select('i.public_id,i.quantity,i.unit_cost,i.line_cost_amount,i.line_number,p.public_id product_public_id,p.name product_name,p.unit_name')->join('products p','p.tenant_id=i.tenant_id AND p.id=i.product_id')->join('stock_intakes si','si.id=i.stock_intake_id')->where(['i.tenant_id'=>$c->tenantId,'i.shop_id'=>$c->shopId,'si.public_id'=>strtolower($id)])->orderBy('i.line_number','ASC')->get()->getResultArray();$h['movements']=$h['status']==='POSTED'?$this->database->table('stock_movements m')->select('m.public_id,m.movement_type,m.quantity_delta,m.unit_cost_basis,m.quantity_before,m.quantity_after,m.average_cost_before,m.average_cost_after,m.occurred_at,m.posted_at,p.name product_name,p.unit_name,u.username actor_name')->join('products p','p.tenant_id=m.tenant_id AND p.id=m.product_id')->join('users u','u.id=m.created_by_user_id')->join('stock_intake_items i','i.id=m.stock_intake_item_id')->join('stock_intakes si','si.id=i.stock_intake_id')->where(['m.tenant_id'=>$c->tenantId,'m.shop_id'=>$c->shopId,'si.public_id'=>strtolower($id)])->orderBy('i.line_number','ASC')->get()->getResultArray():[];return $h;}
 /** @return list<array<string,mixed>> */ public function productHistory(ShopContext $c,string $productPublicId): array{$product=$this->database->table('products')->select('id')->where(['tenant_id'=>$c->tenantId,'public_id'=>strtolower($productPublicId)])->get()->getRowArray();if(!$product)throw new ApiException('PRODUCT_NOT_FOUND','The Product was not found.',404);return $this->database->table('stock_movements m')->select('m.public_id,m.movement_type,m.quantity_delta,m.unit_cost_basis,m.quantity_before,m.quantity_after,m.average_cost_before,m.average_cost_after,m.occurred_at,m.posted_at,u.username actor_name,si.public_id intake_public_id,si.reference')->join('users u','u.id=m.created_by_user_id')->join('stock_intake_items i','i.id=m.stock_intake_item_id')->join('stock_intakes si','si.id=i.stock_intake_id')->where(['m.tenant_id'=>$c->tenantId,'m.shop_id'=>$c->shopId,'m.product_id'=>$product['id']])->orderBy('m.posted_at','DESC')->orderBy('m.id','DESC')->get(50)->getResultArray();}

}
